const dayKey = (d = new Date()) => d.getFullYear() + '-' + String(d.getMonth() + 1).padStart(2, '0') + '-' + String(d.getDate()).padStart(2, '0');
function shiftNo(d = new Date()) { const a = new Date(d.getFullYear(), d.getMonth(), d.getDate()); return Math.max(1, Math.round((a - LAUNCH) / 86400000) + 1); }
const levelOf = (d = new Date()) => (d.getDay() + 6) % 7;
