/* ---------- usage events ----------
   The game reports what happens; the host decides where it goes. Inside a claude.ai artifact nothing leaves the page:
   the host blocks outside requests and gives outside visitors no storage. Served from our own site, each event goes to
   the page that embeds the game (postMessage to TRACK_PARENTS), to dataLayer, Plausible or Umami when the page has them, and to
   TRACK_URL when it is set. No personal data: a random id per page load, nothing else about the visitor. */
const EDITION = 'night', TRACK_URL = '', TRACK_PARENTS = ['https://aldenteai.com', 'https://www.aldenteai.com'];
const T = (() => {
  const sid = Math.random().toString(36).slice(2, 10) + Date.now().toString(36), log = []; let n = 0;
  return { log, send(e, p = {}) {
    const ev = { e, n: n++, sid, ed: EDITION, t: Date.now(), day: dayKey(), ...p };
    log.push(ev); if (log.length > 300) log.shift();
    try { window.dispatchEvent(new CustomEvent('orderup', { detail: ev })); } catch (x) { /* no events */ }
    try { if (window.parent !== window) TRACK_PARENTS.forEach(o => window.parent.postMessage({ source: 'orderup', event: ev }, o)); } catch (x) { /* no parent */ }
    try { if (Array.isArray(window.dataLayer)) window.dataLayer.push({ event: 'orderup_' + e, orderup: ev }); } catch (x) { /* no dataLayer */ }
    try { if (typeof window.plausible === 'function') window.plausible('orderup_' + e, { props: { ...p, edition: EDITION } }); } catch (x) { /* no plausible */ }
    try { if (window.umami && typeof window.umami.track === 'function') window.umami.track('Game ' + e.replace(/_/g, ' '), { ...p, edition: EDITION }); } catch (x) { /* no umami */ }
    try { if (TRACK_URL && navigator.sendBeacon) navigator.sendBeacon(TRACK_URL, JSON.stringify(ev)); } catch (x) { /* no beacon */ }
  } };
})();

