    while (count(cs) > 1 && pool.length) { const c = pool.pop(); if (count(cs.concat(c)) < count(cs)) cs.push(c); }
    for (const p of rng.shuffle(all[0])) { if (count(cs) <= 1) break; if (got[p] !== p) cs.push({ p, x: got[p], eq: true }); }
    for (const c of rng.shuffle(cs.filter(c => !c.base))) { const w = cs.filter(x => x !== c); if (count(w) === 1) cs = w; }
    const msgs = rng.shuffle(got.map((g, p) => {
      const o = items[p], mine = cs.filter(c => c.p === p && !c.base), dir = mine.find(c => c.eq), nots = mine.filter(c => !c.eq).map(c => items[c.x]);
      if (g === p) return { p, stars: 5, text: rng.pick([`My ${o} came just right. Thank you!`, `Got my ${o}, still warm. Five stars.`]) };
      if (dir) return { p, stars: 1, text: `I ordered the ${o} and got the ${items[g]}. Really?` };
      const tail = nots.length === 2 ? ` It is not the ${nots[0]} or the ${nots[1]} either.` : nots.length === 1 ? rng.pick([` At least it is not the ${nots[0]}.`, ` Good thing it is not the ${nots[0]}.`]) : '';
      return { p, stars: nots.length ? 2 : 1, text: rng.pick([`Not what I ordered. Where is my ${o}?`, `Wrong bag. Where is my ${o}?`]) + tail };
    }));
