  head: (g) => g === 'clean' ? 'Mix-up solved in one check.' : g === 'late' ? 'Mix-up solved on the second check.' : 'Every order refunded.',
  sub: (g, st) => g === 'lost' ? `Nobody knew who got what. Refunds ${money(st.stake)}.` : 'Each guest gets the right fix.',
  quote: { clean: ['Guest', 'Sorted in minutes. Thank you.'], late: ['Guest', 'Fixed, but it took a while.'], lost: ['Guest', 'Wrong order and slow support. One star.'] },
