    if (kind === 'swap') { const c = rng.pick(lines.filter(l => SIB[l.item] && l.qty === 1 && !lines.some(x => x.item === SIB[l.item]))); err = { i: lines.indexOf(c), item: c.item, got: SIB[c.item], have: 0 }; }
