    if (kind === 'short') { const c = rng.pick(lines.filter(l => ['fries', 'nuggets', 'cookie', 'ranch', 'bbq', 'cola', 'lemonade'].includes(l.item))); c.qty = 2; err = { i: lines.indexOf(c), item: c.item, have: 1 }; }
    const ids = [];
    lines.forEach((l, i) => { for (let q = 0; q < l.qty; q++) { if (err && err.i === i) { if (err.got) ids.push(err.got); else if (q < err.have) ids.push(l.item); } else ids.push(l.item); } });
