  head: (g, st) => g === 'lost' ? (st.packed ? 'Refund paid for a packed item.' : 'Wrong proof. The refund went through.') : st.packed ? 'The packing clip answers the claim.' : 'Fair refund. Claim closed.',
  sub: (g, st) => g === 'lost' ? `Refund paid: ${money(st.stake)}.` : st.packed ? `The ${NAME[st.item]} went in at ${st.time}. The clip is in the evidence pack.` : `No ${NAME[st.item]} in the clip. Refund ${money(st.stake)}.`,
