  const q = d.quote[grade];
  const res = { id: d.id, title: d.title, grade, stars: { clean: 5, late: 3, lost: 1 }[grade], used: cur.used, par: st.par, hinted: cur.hinted, loss, fee: grade !== 'lost' && !!loss, who: f(q[0]), text: f(q[1]), head: d.head(grade, st, cur.used), sub: d.sub(grade, st) };
  G.results.push(res); T.send('round_end', { id: d.id, idx: G.idx, grade, used: cur.used, par: st.par, hinted: cur.hinted, loss });
  cur.mood = grade === 'clean' ? 0 : grade === 'late' ? 1 : 3; cur.who(); S.amb(cur.amb(grade === 'lost' ? 3 : 0));
  if (grade === 'lost') cur.bubble(d.lostLine ? d.lostLine(st) : d.lines(st)[3]); else cur.bubble((f(d.after) || ['Thank you!', 'About time.'])[grade === 'clean' ? 0 : 1]);
