    const s = store.get('streak', { n: 0, last: '' }), y = new Date(); y.setDate(y.getDate() - 1);
    if (s.last !== day) { store.set('streak', { n: s.last === dayKey(y) ? s.n + 1 : 1, last: day }); const h = store.get('hist', { played: 0, best: 0 }); store.set('hist', { played: h.played + 1, best: Math.max(h.best, G.results.filter(r => r.grade === 'clean').length) }); }
