  if (a === 'share') return shareBox();
  if (a === 'save') return saveCard();
  if (a === 'ig') return shareIg();
  if (a === 'more') return shareMore();
  if (a === 'copy') { T.send('share', { via: 'copy' }); const t = shareText(); const fb = () => { if (!$('#r-ta')) { const ta = document.createElement('textarea'); ta.id = 'r-ta'; ta.className = 'r-ta'; ta.value = t; ($('.modal') || $('.rep')).appendChild(ta); ta.select(); } toast('Select the text and copy it'); }; try { navigator.clipboard.writeText(t).then(() => toast('Copied'), fb); } catch (err) { fb(); } return; }
